import sqlite3

def handle(query, state):
    flag = state.get("flag", "")
    search = (query.get("search") or [""])[0]

    conn = sqlite3.connect(":memory:")
    cur = conn.cursor()

    cur.execute(
        "CREATE TABLE items (id INTEGER PRIMARY KEY, title TEXT, description TEXT, category TEXT)"
    )
    cur.execute(
        "CREATE TABLE metadata (id INTEGER PRIMARY KEY, key TEXT, value TEXT)"
    )
    cur.executemany(
        "INSERT INTO items (title, description, category) VALUES (?, ?, ?)",
        [
            ("Item A", "First description", "General"),
            ("Item B", "Second description", "Special"),
            ("Item C", "Third description", "General"),
        ],
    )
    cur.executemany(
        "INSERT INTO metadata (key, value) VALUES (?, ?)",
        [("version", "1.0"), ("admin_token", flag), ("api_key", "secret123")],
    )
    conn.commit()

    sql = "SELECT title, description FROM items WHERE category = '" + search + "'"
    try:
        cur.execute(sql)
        rows = cur.fetchall()
    except sqlite3.Error as e:
        conn.close()
        return 500, {"Content-Type": "text/plain"}, "DB error: " + str(e)

    conn.close()

    if not rows:
        return 200, {"Content-Type": "text/plain"}, "No items found."

    lines = []
    for row in rows:
        lines.append("|".join(str(c) for c in row))
    return 200, {"Content-Type": "text/plain"}, "\n".join(lines)
